text:
net beside

(queued) -job-> [start]
[start] -job-> (running)
(running) -job-> [finish]
[finish] -job-> (done)
(switch) -flag->? [start]
(switch) -flag->? [finish]
(budget) -credit->? [start]

(switch) annotation fusion true
(budget) annotation fusion true

view lanes position [start] at {"x":0,"y":200}
view lanes position [finish] relative [start] + {"x":0,"y":-200}
view lanes_lock position [start] at {"x":0,"y":200}
view lanes_lock position (switch) at {"x":40,"y":0}
view lanes_lock position (done) relative (switch) + {"x":80,"y":0}
view lanes_lock position [finish] relative [start] + {"x":0,"y":-200}
decorate (budget) beside
decorate (switch) beside left
extensions {}
